fn r#test_timeout_terminates_child_processes_and_cleans_profile(__args: Args) -> Object {
    let mut r#tmp_path = __args.bind(0, "tmp_path", None);
    let mut r#monkeypatch = __args.bind(1, "monkeypatch", None);
    let mut r#app = Object::Unbound;
    let mut r#capture = Object::Unbound;
    let mut r#child_code = Object::Unbound;
    let mut r#marker = Object::Unbound;
    let mut r#profile = Object::Unbound;
    let mut r#report = Object::Unbound;
    let mut r#script = Object::Unbound;
    r#app = object::div(
        &object::local(&r#tmp_path, "tmp_path"),
        &object::str_("vectora-app"),
    );
    object::call_method(
        &object::local(&r#app, "app"),
        "touch",
        Args::new(vec![], vec![]),
    );
    r#capture = object::div(
        &object::local(&r#tmp_path, "tmp_path"),
        &object::str_("profile-path.txt"),
    );
    r#marker = object::div(
        &object::local(&r#tmp_path, "tmp_path"),
        &object::str_("child-finished.txt"),
    );
    r#script = object::div(
        &object::local(&r#tmp_path, "tmp_path"),
        &object::str_("timeout.py"),
    );
    r#child_code = object::fstring(vec![
        object::str_("import time; from pathlib import Path; time.sleep(0.7); Path("),
        object::format_value(
            &object::call(
                &object::name("builtins.str"),
                Args::new(vec![object::local(&r#marker, "marker")], vec![]),
            ),
            "r",
            "",
        ),
        object::str_(").write_text('alive')"),
    ]);
    object::call_method(
        &object::local(&r#script, "script"),
        "write_text",
        Args::new(
            vec![object::fstring(vec![
                object::str_(
                    "import os, subprocess, sys, time\nfrom pathlib import Path\nPath(os.environ['EVAL_CAPTURE']).write_text(os.environ['VECTORA_HOME'])\nsubprocess.Popen([sys.executable, '-c', ",
                ),
                object::format_value(&object::local(&r#child_code, "child_code"), "r", ""),
                object::str_("])\ntime.sleep(10)\n"),
            ])],
            vec![("encoding", object::str_("utf-8"))],
        ),
    );
    object::call_method(
        &object::local(&r#monkeypatch, "monkeypatch"),
        "setenv",
        Args::new(
            vec![
                object::str_("EVAL_CAPTURE"),
                object::call(
                    &object::name("builtins.str"),
                    Args::new(vec![object::local(&r#capture, "capture")], vec![]),
                ),
            ],
            vec![],
        ),
    );
    r#_python_app(Args::new(
        vec![
            object::local(&r#monkeypatch, "monkeypatch"),
            object::local(&r#script, "script"),
        ],
        vec![],
    ));
    r#report = object::call(
        &object::name("backend.evaluation.installed.run_installed_smoke"),
        Args::new(
            vec![object::local(&r#app, "app")],
            vec![("timeout_seconds", Object::Float(0.1))],
        ),
    );
    object::call(
        &object::name("time.sleep"),
        Args::new(vec![Object::Float(0.9)], vec![]),
    );
    object::assert_(
        &object::cmp_eq(
            &object::getattr(&object::local(&r#report, "report"), "status"),
            &object::str_("failed"),
        ),
        "unit/test_eval_installed.py:256",
        None,
    );
    object::assert_(
        &object::in_(&object::str_("não concluiu"), &{
            let __left = object::getattr(&object::local(&r#report, "report"), "reason");
            if object::truthy(&__left) {
                __left
            } else {
                object::str_("")
            }
        }),
        "unit/test_eval_installed.py:257",
        None,
    );
    r#profile = object::call(
        &object::name("pathlib.Path"),
        Args::new(
            vec![object::call_method(
                &object::local(&r#capture, "capture"),
                "read_text",
                Args::new(vec![], vec![("encoding", object::str_("utf-8"))]),
            )],
            vec![],
        ),
    );
    object::assert_(
        &object::not(&object::call_method(
            &object::local(&r#profile, "profile"),
            "exists",
            Args::new(vec![], vec![]),
        )),
        "unit/test_eval_installed.py:259",
        None,
    );
    object::assert_(
        &object::not(&object::call_method(
            &object::local(&r#marker, "marker"),
            "exists",
            Args::new(vec![], vec![]),
        )),
        "unit/test_eval_installed.py:260",
        None,
    );
    Object::None
}

